# Report ricerca: Filament panel + gestione `sport_type` in strava-log

## 0. Versioni (composer.json / composer.lock)

`/home/sirfaenor/Progetti/www/strava-log/public_html/composer.json`:
- PHP `^8.3`
- `laravel/framework`: `^13.0`
- `filament/filament`: `^3.3` → risolto in **Filament v3.3.54** (composer.lock)
- Nessun altro pacchetto Filament plugin extra (solo il core `filament/filament`)

Sintassi da usare: **Filament v3** — classi `Filament\Pages\Page`, `Filament\Widgets\Widget` / `ChartWidget` / `StatsOverviewWidget` / `TableWidget`, tabelle con `->query()` su `Filament\Tables\Table`, form con `Filament\Forms\Form`, niente Livewire "puro" custom (i widget estendono le classi Filament, non componenti Livewire manuali).

---

## 1. `app/Models/Activity.php` (contenuto completo)

```php
<?php

namespace App\Models;

use App\Enums\ActivityType;
use Carbon\Carbon;
use DateTimeInterface;
use Illuminate\Database\Eloquent\Builder;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\SoftDeletes;

/**
 * A single activity by an user
 */
class Activity extends Model
{
    use SoftDeletes;

    protected $casts = [
        'type' => ActivityType::class,
    ];

    protected $table = 'activities';

    protected $fillable = [
        "user_id", "ext_id", "ext_user_id", "name", "distance", "moving_time",
        "elapsed_time", "total_elevation_gain", "type", "sport_type",
        "start_date", "start_date_local", "end_date", "end_date_local",
        "timezone", "utc_offset", "manual", "flagged", "average_speed",
        "max_speed", "gear_id", "location_city", "location_state",
        "location_country", 'calories', 'raw_data',
    ];

    protected static function boot()
    {
        parent::boot();
    }

    public function user()
    {
        return $this->belongsTo("App\User");
    }

    public function scopeValid($query)
    {
        // teoricamente la condizione su race_week non serve,
        // la inserisco per comodità nel fare i test
        return $query->where([['eligible', 1], ["race_week", '>', 0]]);
    }

    public function scopeForWeek($query, $week_number)
    {
        return $query->where('race_week', $week_number);
    }

    public static function mapFromStrava(array $data): array
    {
        return [
            'ext_user_id' => $data['athlete']['id'],
            'name' => $data['name'],
            'distance' => $data['distance'],
            'moving_time' => $data['moving_time'],
            'elapsed_time' => $data['elapsed_time'],
            'total_elevation_gain' => $data['total_elevation_gain'],
            'type' => $data['type'],
            'sport_type' => $data['sport_type'],
            'start_date' => Carbon::parse($data['start_date']),
            'start_date_local' => Carbon::parse($data['start_date_local']),
            'end_date' => Carbon::parse($data['start_date'])->addSeconds($data['elapsed_time']),
            'end_date_local' => Carbon::parse($data['start_date_local'])->addSeconds($data['elapsed_time']),
            'timezone' => $data['timezone'],
            'gear_id' => $data['gear_id'],
            'calories' => $data['calories'] ?? null,
            'average_speed' => $data['average_speed'],
            'max_speed' => $data['max_speed'],
            'description' => $data['description'] ?? null,
            'location_city' => $data['location_city'],
            'location_state' => $data['location_state'],
            'location_country' => $data['location_country'],
            'raw_data' => json_encode($data),
        ];
    }

    public function scopeFrom(Builder $query, DateTimeInterface $date)
    {
        return $query->where('start_date', '>=', $date);
    }

    public function scopeTo(Builder $query, DateTimeInterface $date)
    {
        return $query->where('end_date', '<=', $date);
    }
}
```

**Punti chiave:**
- Esistono `scopeValid`/`scopeForWeek` ma sono **legacy** (fanno riferimento a colonne `eligible`/`race_week` non più usate dai widget Filament attuali — i widget filtrano sempre "a mano" con `where('user_id', auth()->id())` + `whereDate('start_date_local', ...)`, non con questi scope).
- `scopeFrom`/`scopeTo` esistono ma filtrano su `start_date`/`end_date` (UTC), mentre tutto il codice Filament nuovo usa `start_date_local` per i filtri periodo. Da tenere presente se li riusi.
- **Solo `type` è castato** all'enum `ActivityType` (`App\Enums\ActivityType`). **`sport_type` è una stringa grezza, non castata, non ha un proprio enum** — è l'origine del problema di mappatura descritto nel task.
- **Dislivello**: colonna `total_elevation_gain` esiste già (vedi punto 6).
- Nessuna costante/enum per `sport_type` nel modello.

---

## 2. `app/Models/User.php` (contenuto completo)

```php
<?php

namespace App\Models;

use Exception;
use Illuminate\Contracts\Auth\MustVerifyEmail;
use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\SoftDeletes;
use Illuminate\Foundation\Auth\User as Authenticatable;
use Illuminate\Notifications\Notifiable;
use League\OAuth2\Client\Token\AccessTokenInterface;
use Illuminate\Support\Facades\Log;
use DateTime;
use App\Providers\RouteServiceProvider;
use Illuminate\Database\Eloquent\Relations\HasMany;
use Filament\Models\Contracts\FilamentUser;
use Filament\Panel;

class User extends Authenticatable implements FilamentUser
{
    use HasFactory;
    use Notifiable;
    use SoftDeletes;

    protected $fillable = [
        'name', 'email', 'password', "user_id", "ext_id", "username",
        "resource_state", "firstname", "lastname", "city", "state",
        "country", "sex", "premium", "summit", "ext_created_at",
        "ext_updated_at", "badge_type_id", "profile_medium", "profile"
    ];

    protected $hidden = ['password', 'remember_token'];

    protected $casts = ['email_verified_at' => 'datetime'];

    protected static function boot()
    {
        parent::boot();
        // static::addGlobalScope('active', ...) // commentato
    }

    public function canAccessPanel(Panel $panel): bool
    {
        return true;
    }

    public function registerApp(AccessTokenInterface $data) { /* ... collega account Strava ... */ }

    public function isConnected()
    {
        return $this->ext_id !== null && strlen($this->access_token) > 0 && strlen($this->refresh_token) > 0;
    }

    public function getStravaProfileLinkAttribute()
    {
        if(strlen($this->ext_id) === 0) return null;
        return 'https://www.strava.com/athletes/' . $this->ext_id;
    }

    public function activities(): HasMany
    {
        return $this->hasMany(Activity::class, 'user_id');
    }
}
```

**Campi utili per una classifica** (nome da mostrare): `username`, `firstname`, `lastname`, `city`, `profile` (immagine avatar Strava), oltre a `name`/`email` ereditati dal fillable standard Laravel. Non esiste un accessor `full_name` già pronto: andrà costruito (`"{$user->firstname} {$user->lastname}"` o `$user->username`).

`canAccessPanel()` ritorna sempre `true`: **non c'è alcuna restrizione di ruolo/admin** — ogni utente autenticato vede il pannello (e quindi, nell'app attuale, solo i propri dati: tutti i widget filtrano con `auth()->id()`). Per una classifica **multi-utente** dovrai deliberatamente togliere il filtro `where('user_id', auth()->id())` e fare query cross-utente con `join`/`with('user')`.

---

## 3. Struttura `app/Filament/`

```
app/Filament/Concerns/HasActivityPeriodFilter.php
app/Filament/Concerns/HasMonthlyPeriodFilter.php
app/Filament/Pages/Activities.php
app/Filament/Pages/Dashboard.php
app/Filament/Pages/Trend.php
app/Filament/Widgets/ActivitiesTableWidget.php
app/Filament/Widgets/ActivityCountByTypeChartWidget.php
app/Filament/Widgets/ActivityTotalsWidget.php
app/Filament/Widgets/ActivityTypesChartWidget.php
app/Filament/Widgets/CaloriesByTypeChartWidget.php
app/Filament/Widgets/CaloriesShareChartWidget.php
app/Filament/Widgets/Concerns/GroupsActivitiesByType.php
app/Filament/Widgets/DistanceByTypeChartWidget.php
app/Filament/Widgets/DistanceShareChartWidget.php
app/Filament/Widgets/DistanceTrendChartWidget.php
app/Filament/Widgets/ElevationByTypeChartWidget.php
app/Filament/Widgets/ElevationShareChartWidget.php
app/Filament/Widgets/TimeByTypeChartWidget.php
app/Filament/Widgets/TimeShareChartWidget.php
```

**Non esiste `app/Filament/Resources/`** popolato (nessun Resource, la dir non ha file — la discovery punta lì ma è vuota): l'app usa solo **Pages** custom + **Widget**, niente CRUD Resource. Coerente con l'idea di creare la nuova classifica come **Page** custom con eventuali Widget footer/header, seguendo lo stile di `Activities.php`/`Trend.php`.

### `app/Providers/Filament/AdminPanelProvider.php` (completo)

```php
<?php

namespace App\Providers\Filament;

use Filament\Http\Middleware\Authenticate;
use Filament\Http\Middleware\AuthenticateSession;
use Filament\Http\Middleware\DisableBladeIconComponents;
use Filament\Http\Middleware\DispatchServingFilamentEvent;
use App\Filament\Pages\Dashboard;
use Filament\Panel;
use Filament\PanelProvider;
use Filament\Support\Colors\Color;
use Filament\Widgets;
use Illuminate\Cookie\Middleware\AddQueuedCookiesToResponse;
use Illuminate\Cookie\Middleware\EncryptCookies;
use Illuminate\Foundation\Http\Middleware\VerifyCsrfToken;
use Illuminate\Routing\Middleware\SubstituteBindings;
use Illuminate\Session\Middleware\StartSession;
use Illuminate\View\Middleware\ShareErrorsFromSession;

class AdminPanelProvider extends PanelProvider
{
    public function panel(Panel $panel): Panel
    {
        return $panel
            ->default()
            ->id('admin')
            ->path('admin')
            ->login()
            ->passwordReset()
            ->colors(['primary' => Color::Amber])
            ->discoverResources(in: app_path('Filament/Resources'), for: 'App\\Filament\\Resources')
            ->discoverPages(in: app_path('Filament/Pages'), for: 'App\\Filament\\Pages')
            ->pages([
                Dashboard::class,
            ])
            ->discoverWidgets(in: app_path('Filament/Widgets'), for: 'App\\Filament\\Widgets')
            ->widgets([
                // Widgets\AccountWidget::class,
            ])
            ->middleware([ /* stack standard Filament */ ])
            ->authMiddleware([Authenticate::class]);
    }
}
```

**Importante per la nuova pagina**: c'è già `discoverPages(in: app_path('Filament/Pages'), ...)` e `discoverWidgets(...)`, quindi **basta creare la classe nella cartella giusta**, non serve registrarla esplicitamente in `->pages([...])` (a meno che tu voglia impostare un ordine specifico, come fatto solo per `Dashboard::class` perché deve sovrascrivere la home page di default `/admin`). **Nessun `NavigationGroup` è configurato** in nessuna Page (confermato via grep, zero risultati): la nuova pagina comparirà come voce singola in navigazione, ordinabile con `$navigationSort` (attualmente: Activities=1, Dashboard=2, Trend=3 — per una nuova pagina "Classifiche" potresti usare 4).

Le Page esistenti (`Activities`, `Dashboard`, `Trend`) sono lette in dettaglio al punto 4.

---

## 4. Esempi di codice Filament (stile rappresentativo)

### Pages esistenti

`app/Filament/Pages/Dashboard.php`:
```php
class Dashboard extends BaseDashboard
{
    use HasActivityPeriodFilter;

    protected static string $view = 'filament.pages.dashboard';
    protected static ?int $navigationSort = 2;

    public static function getNavigationIcon(): string | Htmlable | null { return 'heroicon-o-chart-pie'; }
    public static function getNavigationLabel(): string { return 'Statistiche'; }
    public function getTitle(): string | Htmlable { return 'Statistiche'; }
}
```

`app/Filament/Pages/Activities.php` (Page "semplice" con footer widget, buon modello da copiare per una pagina "Classifiche"):
```php
class Activities extends Page
{
    use HasActivityPeriodFilter;

    protected static ?string $navigationIcon = 'heroicon-o-document-text';
    protected static ?string $navigationLabel = 'Registro attività';
    protected static ?int $navigationSort = 1;
    protected static ?string $title = 'Registro attività';
    protected static string $view = 'filament.pages.activities';

    protected function getFooterWidgets(): array
    {
        return [
            ActivitiesTableWidget::class,
        ];
    }
}
```

`app/Filament/Pages/Trend.php` (usa il filtro **mensile** invece di quello giornaliero — probabilmente il pattern più vicino a quello che ti serve per "classifiche mensili"):
```php
class Trend extends Page
{
    use HasMonthlyPeriodFilter;

    protected static string $view = 'filament.pages.trend';
    protected static ?int $navigationSort = 3;

    public static function getNavigationIcon(): string|Htmlable|null { return 'heroicon-o-presentation-chart-line'; }
    public function getTitle(): string|Htmlable { return 'Trend'; }
    public static function getNavigationLabel(): string { return 'Trend'; }
}
```

### Concerns condivisi (filtri periodo)

`app/Filament/Concerns/HasActivityPeriodFilter.php` e `HasMonthlyPeriodFilter.php`: implementano `HasFiltersForm` di Filament (`Filament\Pages\Dashboard\Concerns\HasFiltersForm`), con override di `mountHasFilters()` per precompilare `startDate`/`endDate` col range reale delle attività dell'utente, un `Select` "preset" (settimana/mese/anno corrente ecc.) e `DatePicker`/`Select` per l'intervallo. `HasMonthlyPeriodFilter` in particolare (usato da `Trend`) genera opzioni **mese per mese** (`getUserActivitiesMonthRange()`) — è l'approccio più adatto a riusare/adattare per una pagina di classifiche mensili, con l'accortezza che oggi filtra solo sulle attività dell'utente loggato (`auth()->id()`), da rimuovere/adattare per una classifica multi-utente.

### Widget: `GroupsActivitiesByType` (trait condiviso dai chart widget)

`app/Filament/Widgets/Concerns/GroupsActivitiesByType.php` — pattern chiave per raggruppare per `type` con filtro periodo:
```php
trait GroupsActivitiesByType
{
    use InteractsWithPageFilters;

    protected function getTypeTotals(string $selectExpression): Collection
    {
        return Activity::query()
            ->where('user_id', auth()->id())
            ->when($this->filters['startDate'] ?? null, fn (Builder $query, $date) => $query->whereDate('start_date_local', '>=', $date))
            ->when($this->filters['endDate'] ?? null, fn (Builder $query, $date) => $query->whereDate('start_date_local', '<=', $date))
            ->selectRaw("type, {$selectExpression} as total")
            ->groupBy('type')
            ->pluck('total', 'type')
            ->sortDesc();
    }

    protected function getTypeMonthlyTotals(string $selectExpression): Collection
    {
        return Activity::query()
            ->where('user_id', auth()->id())
            ->when(...)
            ->selectRaw("type, DATE_FORMAT(start_date_local, '%Y-%m') as month, {$selectExpression} as total")
            ->groupBy('type', 'month')
            ->orderBy('month')
            ->get();
    }

    protected function mapTypeTotalsToRows(Collection $totals, int $maxItems, callable $transform): Collection { /* etichette/colori da ActivityType */ }
    protected function colorToRgb(array $color): string { return "rgb({$color[500]})"; }
}
```

### Widget "ChartWidget" (esempio `DistanceByTypeChartWidget`):
Estende `Filament\Widgets\ChartWidget`, usa `getType()` (`'bar'`), `getData()` con `datasets`/`labels`, `getOptions()` con `RawJs::make(<<<'JS' ... JS)` per personalizzare Chart.js (tooltip, assi).

### Widget "StatsOverviewWidget" (esempio `ActivityTotalsWidget`, completo sopra al punto letto): estende `Filament\Widgets\StatsOverviewWidget`, ritorna array di `Stat::make(...)->icon(...)`. **Ottimo modello per le card di sintesi** (distanza totale, dislivello totale, ecc.) di una pagina classifiche.

### Widget "TableWidget" (esempio `ActivitiesTableWidget`, completo sopra): estende `Filament\Widgets\TableWidget`, implementa `table(Table $table): Table` con `->query(...)`, colonne `Tables\Columns\TextColumn` / `IconColumn`, azione `ViewAction::make()->slideOver()->infolist(...)`. **Questo è il modello più utile per la tabella classifica** (colonne ordinabili, formattazione custom via `formatStateUsing`).

Nota di stile ricorrente: `where('user_id', auth()->id())` + `whereDate('start_date_local', ...)` ripetuto identico in quasi tutti i widget — replicalo per coerenza ma **valuta di astrarlo** in uno scope Eloquent nuovo (es. `scopeForUser`/`scopeInPeriod`) dato che lo scriverai di nuovo per la classifica.

---

## 5. Dove/come viene filtrato `sport_type` — la "a piedi" attuale

**Risultato del grep**: `sport_type` compare **solo** in:
- `app/Models/Activity.php` (fillable + `mapFromStrava`, righe 51 e 129) — viene solo salvato, mai letto/filtrato altrove
- migrazione `database/migrations/2023_06_22_074639_update_activities.php` (definizione colonna)

**Nessun job, scope o config filtra effettivamente per `sport_type`.** Tutto il filtraggio "a piedi" nell'app è in realtà basato sul campo legacy **`type`** (castato all'enum `App\Enums\ActivityType`), non su `sport_type`:

- `app/Enums/ActivityType.php` — enum chiuso con **tutti** i valori storici del vecchio campo Strava `type` (`Run`, `Ride`, `Walk`, `Hike`, `VirtualRun`, `Swim`, `Yoga`, ecc. — 37 case totali). **Non esiste il case `TrailRun`** perché nel vecchio campo `type` di Strava il trail running viene semplicemente riportato come `Run` (il campo `type` legacy è meno granulare del nuovo `sport_type`).
- Il metodo `getSpeedUnit()` dell'enum è dove oggi si decide "chi è a piedi":
  ```php
  public function getSpeedUnit(): SpeedUnit
  {
      return match ($this) {
          self::Run, self::VirtualRun, self::Walk, self::Hike, self::Snowshoe => SpeedUnit::MinutesPerKilometer,
          default => SpeedUnit::KilometersPerHour,
      };
  }
  ```
  Questo è l'unico punto di codice che raggruppa esplicitamente attività "a piedi" (`Run`, `VirtualRun`, `Walk`, `Hike`, `Snowshoe`), ma è basato su `type`, non su `sport_type`, e serve solo per scegliere l'unità di velocità (passo vs km/h), non per filtrare query.
- Esiste anche un **secondo enum**, distinto e apparentemente ridotto/legacy, `app/Domain/Activity/ActivityTypeEnum.php`:
  ```php
  enum ActivityTypeEnum: string
  {
      case RUN = 'Run';
      case RIDE = 'Ride';
      case WALK = 'Walk';
  }
  ```
  Usato solo da `app/Console/Commands/ActivitiesStats.php` e `app/Domain/StatsCalculator.php` (comando artisan `activities:stats`, sembra un abbozzo di funzionalità mai completata: `StatsCalculator` ha solo setter, nessun metodo di calcolo effettivo). **Non è collegato al pannello Filament.**
- `app/Jobs/SyncUserActivities.php` (job di sync da Strava): **non applica alcun filtro per tipo di attività** — salva tutte le attività restituite dall'API Strava tramite `Activity::firstOrCreate(['ext_id' => ...], array_merge(['user_id' => ...], Activity::mapFromStrava($activityData)))`. Il fatto che "l'app al momento mostra solo attività a piedi" è quindi solo un effetto dei dati reali dell'utente/dataset attuale, **non un filtro nel codice**.

### Conseguenza pratica per il tuo task
Poiché **`sport_type` non ha un cast/enum dedicato** (è una stringa grezza da Strava, valori reali tipici: `Run`, `TrailRun`, `Walk`, `Hike`, oltre a tutti gli altri sport supportati da Strava come `MountainBikeRide`, `GravelRide`, `VirtualRide`, ecc. — valori Strava "moderni", più granulari del vecchio `type`), per la classifica filtrabile dovrai:
1. Verificare i valori realmente presenti in tabella (query `SELECT DISTINCT sport_type FROM activities` — non ho potuto eseguirla: il container PHP-FPM locale non è avviato, `systemctl --user start lerd-php85-fpm` per riprovare);
2. Decidere se creare un **nuovo enum `SportType`** (analogo ad `ActivityType` ma sui valori Strava moderni) oppure semplicemente **filtrare per array di stringhe** (`whereIn('sport_type', ['Run', 'TrailRun', 'Walk', 'Hike'])`) nella nuova pagina classifiche, dato che oggi non esiste nessuna infrastruttura di mappatura riutilizzabile per `sport_type`.

---

## 6. Colonna dislivello (elevation gain)

Sì, esiste già: **`total_elevation_gain`**, colonna DB dalla migrazione `2023_06_22_074639_update_activities.php`:
```php
$table->unsignedBigInteger('total_elevation_gain')->nullable();
```
Popolata in `Activity::mapFromStrava()` (`'total_elevation_gain' => $data['total_elevation_gain']`), inclusa nel `$fillable` del modello, ed **già usata** in:
- `ActivityTotalsWidget` (somma totale, Stat card)
- `ActivitiesTableWidget` (colonna tabella + infolist del dettaglio)
- `ElevationByTypeChartWidget` / `ElevationShareChartWidget` (grafici per tipo)

Nessuna migrazione successiva la modifica; nessun'altra colonna simile (no `elevation_high`/`elevation_low`).

---

## Riepilogo per la nuova pagina "Classifiche mensili"

- **Versioni**: Laravel 13, Filament v3.3.54 (PHP 8.3) → sintassi Filament v3 standard.
- **Dove creare**: `app/Filament/Pages/Leaderboard.php` (o nome simile) — auto-discoverata, nessuna registrazione manuale necessaria in `AdminPanelProvider`.
- **Filtro periodo mensile**: riusa/adatta `App\Filament\Concerns\HasMonthlyPeriodFilter` (già pensato per granularità mensile), ma **rimuovi/parametrizza** il vincolo `auth()->id()` presente in tutti i metodi (`getUserActivitiesMonthRange`, ecc.) se la classifica deve confrontare più utenti.
- **Filtro tipo attività**: non esiste un meccanismo pronto su `sport_type` — dovrai introdurlo ex novo (nuovo enum o whitelist di stringhe), dato che tutto il codice attuale ragiona sul campo `type`/`ActivityType`.
- **Metriche richieste** (distanza, velocità media, dislivello) sono già tutte disponibili come colonne dirette su `activities` (`distance`, `average_speed`, `total_elevation_gain`), niente da aggiungere allo schema.
- **Stile widget**: per la tabella classifica, ricalca `ActivitiesTableWidget` (TableWidget con `->query()`); per riepiloghi, `ActivityTotalsWidget` (StatsOverviewWidget); per grafici, `DistanceByTypeChartWidget`/trait `GroupsActivitiesByType` come riferimento per raggruppare ed etichettare.

# Report ricerca: Filament panel + gestione `sport_type` in strava-log

## 0. Versioni (composer.json / composer.lock)

`/home/sirfaenor/Progetti/www/strava-log/public_html/composer.json`:
- PHP `^8.3`
- `laravel/framework`: `^13.0`
- `filament/filament`: `^3.3` → risolto in **Filament v3.3.54** (composer.lock)
- Nessun altro pacchetto Filament plugin extra (solo il core `filament/filament`)

Sintassi da usare: **Filament v3** — classi `Filament\Pages\Page`, `Filament\Widgets\Widget` / `ChartWidget` / `StatsOverviewWidget` / `TableWidget`, tabelle con `->query()` su `Filament\Tables\Table`, form con `Filament\Forms\Form`, niente Livewire "puro" custom (i widget estendono le classi Filament, non componenti Livewire manuali).

---

## 1. `app/Models/Activity.php` (contenuto completo)

```php
<?php

namespace App\Models;

use App\Enums\ActivityType;
use Carbon\Carbon;
use DateTimeInterface;
use Illuminate\Database\Eloquent\Builder;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\SoftDeletes;

/**
 * A single activity by an user
 */
class Activity extends Model
{
    use SoftDeletes;

    protected $casts = [
        'type' => ActivityType::class,
    ];

    protected $table = 'activities';

    protected $fillable = [
        "user_id", "ext_id", "ext_user_id", "name", "distance", "moving_time",
        "elapsed_time", "total_elevation_gain", "type", "sport_type",
        "start_date", "start_date_local", "end_date", "end_date_local",
        "timezone", "utc_offset", "manual", "flagged", "average_speed",
        "max_speed", "gear_id", "location_city", "location_state",
        "location_country", 'calories', 'raw_data',
    ];

    protected static function boot()
    {
        parent::boot();
    }

    public function user()
    {
        return $this->belongsTo("App\User");
    }

    public function scopeValid($query)
    {
        // teoricamente la condizione su race_week non serve,
        // la inserisco per comodità nel fare i test
        return $query->where([['eligible', 1], ["race_week", '>', 0]]);
    }

    public function scopeForWeek($query, $week_number)
    {
        return $query->where('race_week', $week_number);
    }

    public static function mapFromStrava(array $data): array
    {
        return [
            'ext_user_id' => $data['athlete']['id'],
            'name' => $data['name'],
            'distance' => $data['distance'],
            'moving_time' => $data['moving_time'],
            'elapsed_time' => $data['elapsed_time'],
            'total_elevation_gain' => $data['total_elevation_gain'],
            'type' => $data['type'],
            'sport_type' => $data['sport_type'],
            'start_date' => Carbon::parse($data['start_date']),
            'start_date_local' => Carbon::parse($data['start_date_local']),
            'end_date' => Carbon::parse($data['start_date'])->addSeconds($data['elapsed_time']),
            'end_date_local' => Carbon::parse($data['start_date_local'])->addSeconds($data['elapsed_time']),
            'timezone' => $data['timezone'],
            'gear_id' => $data['gear_id'],
            'calories' => $data['calories'] ?? null,
            'average_speed' => $data['average_speed'],
            'max_speed' => $data['max_speed'],
            'description' => $data['description'] ?? null,
            'location_city' => $data['location_city'],
            'location_state' => $data['location_state'],
            'location_country' => $data['location_country'],
            'raw_data' => json_encode($data),
        ];
    }

    public function scopeFrom(Builder $query, DateTimeInterface $date)
    {
        return $query->where('start_date', '>=', $date);
    }

    public function scopeTo(Builder $query, DateTimeInterface $date)
    {
        return $query->where('end_date', '<=', $date);
    }
}
```

**Punti chiave:**
- Esistono `scopeValid`/`scopeForWeek` ma sono **legacy** (fanno riferimento a colonne `eligible`/`race_week` non più usate dai widget Filament attuali — i widget filtrano sempre "a mano" con `where('user_id', auth()->id())` + `whereDate('start_date_local', ...)`, non con questi scope).
- `scopeFrom`/`scopeTo` esistono ma filtrano su `start_date`/`end_date` (UTC), mentre tutto il codice Filament nuovo usa `start_date_local` per i filtri periodo. Da tenere presente se li riusi.
- **Solo `type` è castato** all'enum `ActivityType` (`App\Enums\ActivityType`). **`sport_type` è una stringa grezza, non castata, non ha un proprio enum** — è l'origine del problema di mappatura descritto nel task.
- **Dislivello**: colonna `total_elevation_gain` esiste già (vedi punto 6).
- Nessuna costante/enum per `sport_type` nel modello.

