<?php

namespace App\Enums;

/**
 * Unità di misura per la velocità, memorizzata in origine in metri al secondo.
 */
enum SpeedUnit: string
{
    case KilometersPerHour = 'km/h';
    case MinutesPerKilometer = 'min/km';

    public function format(?float $metersPerSecond): string
    {
        if (! $metersPerSecond) {
            return '—';
        }

        return match ($this) {
            self::KilometersPerHour => number_format($metersPerSecond * 3.6, 1, ',', '.').' km/h',
            self::MinutesPerKilometer => $this->formatPace($metersPerSecond),
        };
    }

    private function formatPace(float $metersPerSecond): string
    {
        $secondsPerKm = (int) round(1000 / $metersPerSecond);

        return sprintf('%d:%02d min/km', intdiv($secondsPerKm, 60), $secondsPerKm % 60);
    }
}

