3	namespace App\Filament\Widgets;
4	
5	use App\Models\Activity;
6	use Filament\Widgets\Concerns\InteractsWithPageFilters;
7	use Filament\Widgets\StatsOverviewWidget as BaseWidget;
8	use Filament\Widgets\StatsOverviewWidget\Stat;
9	use Illuminate\Database\Eloquent\Builder;
10	
11	/**
12	 * Totali di distanza, tempo in movimento e dislivello
13	 * per il periodo selezionato in dashboard.
14	 */
15	class ActivityTotalsWidget extends BaseWidget
16	{
17	    use InteractsWithPageFilters;
18	
19	    protected static ?int $sort = -1;
20	
21	    protected function getStats(): array
22	    {
23	        $totals = $this->getActivitiesQuery()
24	            ->selectRaw('count(*) as count')
25	            ->selectRaw('coalesce(sum(distance), 0) as distance')
26	            ->selectRaw('coalesce(sum(moving_time), 0) as moving_time')
27	            ->selectRaw('coalesce(sum(total_elevation_gain), 0) as total_elevation_gain')
28	            ->first();
29	
30	        return [
31	            Stat::make('Attività totali', number_format($totals->count, 0, ',', '.'))
32	                ->icon('heroicon-o-bolt'),
33	
34	            Stat::make('Distanza totale', number_format($totals->distance / 1000, 0, ',', '.').' km')
35	                ->icon('heroicon-o-map'),
36	
37	            Stat::make('Tempo totale', $this->formatDuration((int) $totals->moving_time))
38	                ->icon('heroicon-o-clock'),
39	
40	            Stat::make('Dislivello totale', number_format($totals->total_elevation_gain, 0, ',', '.').' m')
41	                ->icon('heroicon-o-arrow-trending-up'),
42	        ];
43	    }
44	
45	    protected function getActivitiesQuery(): Builder
46	    {
47	        return Activity::query()
48	            ->where('user_id', auth()->id())
49	            ->when(
50	                $this->filters['startDate'] ?? null,
51	                fn (Builder $query, $date) => $query->whereDate('start_date_local', '>=', $date)
52	            )
53	            ->when(
54	                $this->filters['endDate'] ?? null,
55	                fn (Builder $query, $date) => $query->whereDate('start_date_local', '<=', $date)
56	            );
57	    }
58	
59	    private function formatDuration(int $seconds): string
60	    {
61	        $hours = intdiv($seconds, 3600);
62	        $minutes = intdiv($seconds % 3600, 60);
63	
64	        return "{$hours} h {$minutes} min";
65	    }
66	}
