3	namespace App\Filament\Widgets\Concerns;
4	
5	use App\Models\User;
6	use Carbon\Carbon;
7	use Filament\Widgets\Concerns\InteractsWithPageFilters;
8	use Illuminate\Database\Eloquent\Builder;
9	
10	/**
11	 * Query base condivisa dai widget di classifica: utenti con almeno
12	 * un'attività nel mese/sport selezionato, con l'aggregato passato come
13	 * $selectExpression esposto come colonna $alias per l'ordinamento.
14	 */
15	trait BuildsLeaderboardQuery
16	{
17	    use InteractsWithPageFilters;
18	
19	    public function updatedFilters(): void
20	    {
21	        $this->resetPage();
22	    }
23	
24	    protected function getLeaderboardQuery(string $selectExpression, string $alias): Builder
25	    {
26	        $month = $this->filters['month'] ?? null;
27	        $sportTypes = $this->filters['sportTypes'] ?? [];
28	
29	        $monthStart = $month ? Carbon::createFromFormat('Y-m', $month) : Carbon::now();
30	
31	        return User::query()
32	            ->select('users.*')
33	            ->selectRaw("{$selectExpression} as {$alias}")
34	            ->join('activities', 'activities.user_id', '=', 'users.id')
35	            ->whereNull('activities.deleted_at')
36	            ->whereBetween('activities.start_date_local', [
37	                $monthStart->copy()->startOfMonth(),
38	                $monthStart->copy()->endOfMonth(),
39	            ])
40	            ->when(
41	                filled($sportTypes),
42	                fn (Builder $query) => $query->whereIn('activities.sport_type', $sportTypes)
43	            )
44	            ->groupBy('users.id')
45	            ->orderByDesc($alias);
46	    }
47	}
